
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ssb_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ssb", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.488071081589401e+00, -4.400380163693431e+00, -4.277903783289702e+00, -4.109140539538019e+00, -3.881241100921784e+00, -3.582759145681345e+00, -3.209833761803347e+00, -2.775788159051017e+00, -2.313751478123919e+00, -1.847799486323671e+00, -1.283940052515558e+00, -7.411028750092418e-01, -6.287802664009859e-01, -5.083026778336970e-01, -3.683395642298478e-01, -2.373773433584817e-01, -1.299549328171502e-01, -4.923922982607472e-02, -1.080874188814340e-02, -1.216198352933693e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


